#!/usr/bin/env bash
# Generates supabase/live/0072_apply.sql for the SQL Editor (live, after its own approval) — ONE
# transaction that stops unless the eight game functions are the verified 0001–0071 versions and
# none of 0072's objects exists, runs supabase/migrations/0072_game_hardening.sql unchanged, and
# rolls everything back unless the result is the verified 0072. A second run stops.
# On staging 0072 goes through the workflow's apply action (migrations: 0072), between the
# m3_0072_preflight and m3_0072_postcheck actions.
#   bash supabase/live/make_0072_apply.sh      (OUT=<dir> writes elsewhere, for the sync check)
set -euo pipefail
cd "$(dirname "$0")/../.."
OUT=${OUT:-supabase/live}
f=supabase/migrations/0072_game_hardening.sql
{
  echo "-- 0072 for LIVE, all or nothing: M3-H game hardening."
  echo "-- Run once in Supabase → SQL Editor: first 0072_preflight.sql (part 1 all ok), then this, then 0072_postcheck.sql."
  echo "-- Generated by supabase/live/make_0072_apply.sh from $f — do not edit by hand."
  echo "begin;"
  echo "set local lock_timeout = '5s';"
  echo "set local statement_timeout = '60s';"
  cat <<'SQL'
do $pre$ begin
  if not ((select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match') = '07d5432f9f203da2a0c7c69ebd72451f' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'leave_match') = 'db6bb484d82740641b72d8448f86ebfa' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join') = 'bce21b2e4e717051f838cc1714cc4e96' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status') = '68feb36c10f79ae33bd6c67db955846f' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match') = 'aa37b42e834acc500cd1f115e2aa4ee3' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match') = '548b94f7c81c4805494564c14f213d73' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'sync_match_with_booking') = '791e9d4948f61fcf788a451ed681420c' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify') = '485b766738b909d27c67c1435c7d28a6'
      and not exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname in ('notify_waiting','remove_player','resolve_court','match_message_guard','push_text'))
      and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'matches' and column_name = 'court_lost_at')) then
    raise exception 'STOPPED, nothing changed: not the verified 0001–0071 + 0067 starting point (0072 already applied, or 0067 missing?)';
  end if;
end $pre$;
SQL
  echo "-- ===== migration 0072, unchanged from $f ====="
  cat "$f"
  echo "-- ===== end of migration 0072 ====="
  cat <<'SQL'
do $post$ begin
  if not ((select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match') = '47e042026bc084f8da0664020b77e1fb' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'leave_match') = '0bb6d58b5415a58c61878d0f4df230dd' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join') = '504c193753ecdda87b461204e1e0243f' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status') = '883dc68e447d0f8a5af681d8f395bf3b' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match') = 'efc91a08d70e84de15fced731b99a03c' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match') = '33b26aae02b8861858f86de235b66264' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'sync_match_with_booking') = '6d2108ade98ace105a863878e8bf9b3d' and (select max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify') = 'c063c6d3f6071aa1a6446682cad26491'
      and exists (select 1 from pg_trigger where tgname = 'match_messages_guard')
      and has_function_privilege('authenticated', 'public.remove_player(uuid,uuid)', 'execute')
      and not has_function_privilege('anon', 'public.remove_player(uuid,uuid)', 'execute')
      and not has_function_privilege('authenticated', 'public.notify_waiting(uuid)', 'execute')
      and not has_function_privilege('authenticated', 'public.push_text(uuid)', 'execute')) then
    raise exception 'ROLLED BACK: the result of 0072 is not the verified version';
  end if;
end $post$;
notify pgrst, 'reload schema';
commit;
select '0072 applied' as result;
SQL
} > "$OUT/0072_apply.sql"
echo "wrote $OUT/0072_apply.sql"
